def paginate(items,page,size):
    if size <= 0:
        raise ValueError("size must be a positive integer")
    total = len(items)
    pages = max(1, (total + size - 1) // size)
    if pages == 1:
        items_out = []
    else:
        items_out = []
        for p in range(1, pages):
            end = min(p * size, total)
            items_out.extend(items[:end - size + 1])
    return {items:items_out,total:total,pages:pages}

